// Server-rendered collection page and admin page.
export const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const color = (c) => (/^#[0-9a-fA-F]{6}$/.test(c || "") ? c : "#7c3aed");

const shell = (c, title, body, extraHead = "") => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title>
<style>body{font:16px system-ui,sans-serif;max-width:36rem;margin:2.5rem auto;padding:0 1rem;color:#111827}h1{color:${color(c)};font-size:1.5rem}label{display:block;font-weight:600;margin:.8rem 0 .2rem}
input,textarea,select,button{font:inherit;padding:.55rem .7rem;border-radius:8px;border:1px solid #9ca3af;width:100%;box-sizing:border-box}input[type=checkbox]{width:auto}button{background:${color(c)};color:#fff;border:0;font-weight:700;cursor:pointer;margin-top:1rem}
.hp{position:absolute;left:-9999px;height:0;overflow:hidden}.note{font-size:.85rem;color:#4b5563}.err{color:#b91c1c;font-weight:700}.card{border:1px solid #e5e7eb;border-radius:10px;padding:.8rem 1rem;margin:.7rem 0}
.row button{width:auto;margin:.3rem .3rem 0 0;padding:.3rem .7rem}</style>${extraHead}</head><body>${body}</body></html>`;

export function renderForm({ form, company, color: c, error }) {
  return shell(c, form.title, `<h1>${esc(form.title)}</h1><p>${esc(form.prompt)}</p>${error ? `<p class="err" role="alert">${esc(error)}</p>` : ""}
<form method="post" action="/t/${esc(form.slug)}"><label for="name">Your name</label><input id="name" name="name" required maxlength="80" autocomplete="name">
<label for="role">Role (optional)</label><input id="role" name="role" maxlength="80"><label for="company">Company (optional)</label><input id="company" name="company" maxlength="80">
<label for="rating">Rating (optional)</label><select id="rating" name="rating"><option value="">No rating</option>${[5, 4, 3, 2, 1].map((n) => `<option value="${n}">${n} out of 5</option>`).join("")}</select>
<label for="text">Your testimonial</label><textarea id="text" name="text" rows="6" required minlength="20" maxlength="600"></textarea>
<label for="email">Email (optional, never published)</label><input id="email" name="email" type="email" maxlength="120" autocomplete="email">
<div class="hp" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div>
<label style="font-weight:400"><input type="checkbox" name="consent" value="on" required> I agree that ${esc(company)} may publish my words and name above on its website and marketing.</label>
<button>Send</button></form><p class="note">${esc(company)} reviews every testimonial before anything is published and does not edit what you wrote.</p>`);
}

export function renderThanks({ company, color: c }) {
  return shell(c, "Thank you", `<h1>Thank you</h1><p>${esc(company)} has your testimonial. It will only appear on their site after they review it.</p>`);
}

// The admin page holds no secrets: it asks for the admin key in the browser and calls the API.
export function renderAdmin({ company, color: c }) {
  return shell(c, `Testimonials · ${company}`, `<h1>${esc(company)} testimonials</h1><label for="k">Admin key</label><input id="k" type="password" autocomplete="off"><button id="go" type="button">Load</button>
<div id="out"></div><p class="note">Approve what you want public; hide the rest. Text is never edited here, only shown or not.</p>
<script>
var out=document.getElementById("out");
function el(t,x){var e=document.createElement(t);if(x)e.textContent=x;return e}
function call(m,p,b){return fetch(p,{method:m,headers:{authorization:"Bearer "+document.getElementById("k").value},body:b?JSON.stringify(b):undefined}).then(function(r){return r.json()})}
function load(){call("GET","/v1/testimonials").then(function(list){out.textContent="";if(!Array.isArray(list)){out.appendChild(el("p","Wrong key."));return}
list.slice().reverse().forEach(function(t){var c=el("div");c.className="card";c.appendChild(el("strong",t.name+(t.company?" · "+t.company:"")+" · "+t.status+(t.rating?" · "+t.rating+"/5":"")));c.appendChild(el("p",t.text));
var row=el("div");row.className="row";["approved","hidden","pending"].forEach(function(s){if(s===t.status)return;var b=el("button",s==="approved"?"Approve":s==="hidden"?"Hide":"Back to pending");b.type="button";b.onclick=function(){call("POST","/v1/testimonials/"+t.id+"/status",{status:s}).then(load)};row.appendChild(b)});c.appendChild(row);out.appendChild(c)})})}
document.getElementById("go").onclick=load;
</script>`);
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted testimonial collection + embeddable wall. Zero dependencies.
//   ADMIN_KEY=... PUBLIC_URL=https://proof.example.com COMPANY_NAME=Acme node server.mjs
import http from "node:http";
import fs from "node:fs";
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { newState, createForm, submit, setStatus, remove, publicWall, stats, toCsv, SLUG_RE } from "./store.mjs";
import { renderForm, renderThanks, renderAdmin } from "./page.mjs";
import { widgetSource } from "./widget.mjs";

export { newState };
const env = process.env;

const readBody = (req, max = 20_000) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > max) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  req.on("error", reject);
});
const bearerOk = (req, key) => {
  const a = Buffer.from(req.headers.authorization || ""), b = Buffer.from(`Bearer ${key}`);
  return Boolean(key) && a.length === b.length && timingSafeEqual(a, b);
};

// cfg: {state, save, adminKey, ipSecret, publicUrl, company, color, notify, trustProxy, now}
export function handler(cfg) {
  const now = cfg.now || Date.now;
  const company = cfg.company || "Our team";
  const ipKey = (req) => {
    const ip = (cfg.trustProxy && String(req.headers["x-forwarded-for"] || "").split(",").pop().trim()) || req.socket.remoteAddress || "?";
    return createHmac("sha256", cfg.ipSecret).update(ip).digest("base64url").slice(0, 16); // a daily counter key, not stored with the testimonial
  };
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json", extra = {}) => {
      res.writeHead(code, { "content-type": type, "cache-control": "no-store", "referrer-policy": "no-referrer", "x-content-type-options": "nosniff", ...extra });
      res.end(typeof body === "string" ? body : JSON.stringify(body));
    };
    const fail = (code, error) => send(code, { error });
    const html = (code, body, csp = "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'") => send(code, body, "text/html; charset=utf-8", { "content-security-policy": csp });
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (url.pathname === "/embed.js" && req.method === "GET") return send(200, widgetSource(), "text/javascript; charset=utf-8", { "cache-control": "public, max-age=3600" });
      if (url.pathname === "/wall.json" && req.method === "GET") {
        const f = url.searchParams.get("form") || "";
        const limit = Math.max(1, Math.min(50, Number(url.searchParams.get("limit")) || 12));
        return send(200, publicWall(cfg.state, f, limit), "application/json", { "access-control-allow-origin": "*", "cache-control": "public, max-age=60" });
      }
      if (url.pathname === "/admin" && req.method === "GET") return html(200, renderAdmin({ company, color: cfg.color }), "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'");

      const t = url.pathname.match(/^\/t\/([a-z0-9-]+)$/);
      if (t) {
        const form = cfg.state.forms[t[1]];
        if (!form) return send(404, "not found\n", "text/plain");
        if (req.method === "GET") return html(200, renderForm({ form, company, color: cfg.color }));
        if (req.method === "POST") {
          const params = Object.fromEntries(new URLSearchParams(await readBody(req)));
          const out = submit(cfg.state, form, params, { ipKey: ipKey(req), now: now(), id: randomBytes(6).toString("hex") });
          if (out.silent) return html(200, renderThanks({ company, color: cfg.color })); // bots and double-clicks look the same as success
          if (out.error) return html(400, renderForm({ form, company, color: cfg.color, error: out.error }));
          cfg.save();
          if (cfg.notify) cfg.notify({ id: out.item.id, name: out.item.name, form: form.slug }).catch((e) => console.error("notify failed:", e.message));
          return html(200, renderThanks({ company, color: cfg.color }));
        }
      }

      if (url.pathname.startsWith("/v1/")) {
        if (!bearerOk(req, cfg.adminKey)) return fail(401, "admin key required");
        if (req.method === "GET" && url.pathname === "/v1/summary") return send(200, stats(cfg.state));
        if (req.method === "GET" && url.pathname === "/v1/testimonials") return send(200, cfg.state.items.slice(-500));
        if (req.method === "GET" && url.pathname === "/v1/testimonials.csv") return send(200, toCsv(cfg.state.items), "text/csv; charset=utf-8", { "content-disposition": 'attachment; filename="testimonials.csv"' });
        if (url.pathname === "/v1/forms") {
          if (req.method === "GET") return send(200, Object.values(cfg.state.forms).map((f) => ({ ...f, collectUrl: `${cfg.publicUrl}/t/${f.slug}` })));
          if (req.method === "POST") {
            const out = createForm(cfg.state, JSON.parse((await readBody(req)) || "{}"), now());
            if (out.error) return fail(400, out.error);
            cfg.save();
            return send(201, { ...out.form, collectUrl: `${cfg.publicUrl}/t/${out.form.slug}`, embed: `<script src="${cfg.publicUrl}/embed.js" data-form="${out.form.slug}" defer></script>` });
          }
        }
        const st = url.pathname.match(/^\/v1\/testimonials\/([a-f0-9]+)(?:\/(status))?$/);
        if (st && req.method === "POST" && st[2]) {
          const out = setStatus(cfg.state, st[1], JSON.parse((await readBody(req)) || "{}").status);
          if (out.error) return fail(out.error.startsWith("no such") ? 404 : 400, out.error);
          cfg.save(); return send(200, out.item);
        }
        if (st && req.method === "DELETE" && !st[2]) {
          const out = remove(cfg.state, st[1]);
          if (out.error) return fail(404, out.error);
          cfg.save(); return send(200, out);
        }
      }
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status && e.status < 500 ? e.status : e instanceof SyntaxError ? 400 : 500, { error: e instanceof SyntaxError ? "invalid JSON" : "Something went wrong." });
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const missing = ["ADMIN_KEY", "PUBLIC_URL"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = Object.assign(newState(), readJson(statePath, {}));
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  if (!Object.keys(state.forms).length) createForm(state, { slug: "default" }, Date.now());
  const notify = env.NOTIFY_WEBHOOK ? async (m) => {
    const r = await fetch(env.NOTIFY_WEBHOOK, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text: `New testimonial from ${m.name} awaiting approval: ${env.PUBLIC_URL}/admin` }) });
    if (!r.ok) throw new Error(`webhook ${r.status}`);
  } : null;
  const cfg = { state, save, adminKey: env.ADMIN_KEY, ipSecret: env.IP_SECRET || randomBytes(16).toString("hex"), publicUrl: env.PUBLIC_URL.replace(/\/$/, ""), company: env.COMPANY_NAME, color: env.BRAND_COLOR, notify, trustProxy: env.TRUST_PROXY === "true" };
  http.createServer(handler(cfg)).listen(Number(env.PORT || 8080), () => console.log(`testimonial-keeper on :${env.PORT || 8080}`));
}

store.mjs.text:
// Testimonial collection rules. Pure functions over a plain-object state; no I/O.
// The same file is used by the server and by the landing-page demo.

export const LIMITS = { name: 80, role: 80, company: 80, text: 600, minText: 20, perIpPerDay: 5, maxItems: 5000, maxForms: 200 };
export const SLUG_RE = /^[a-z0-9][a-z0-9-]{1,31}$/;

export const newState = () => ({ forms: {}, items: [], rate: {} });

const clean = (s, max) => String(s ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f‪-‮⁦-⁩]/g, "").replace(/[ \t]+/g, " ").trim().slice(0, max);

export function createForm(state, { slug, title, prompt }, now) {
  const s = String(slug || "").toLowerCase();
  if (!SLUG_RE.test(s)) return { error: "slug must be 2-32 characters: a-z, 0-9 or -" };
  if (state.forms[s]) return { error: "that slug is taken" };
  if (Object.keys(state.forms).length >= LIMITS.maxForms) return { error: "form limit reached" };
  const form = { slug: s, title: clean(title, 80) || "Share your experience", prompt: clean(prompt, 240) || "What did you use us for, and what changed?", createdAt: now };
  state.forms[s] = form;
  return { form };
}

// A submission needs an explicit consent tick: nothing is published without the
// person's permission, and nothing is published without the owner's approval.
export function submit(state, form, input, { ipKey, now, id }) {
  if (clean(input.website, 200)) return { error: "ignored", silent: true }; // honeypot: bots fill every field
  const name = clean(input.name, LIMITS.name), text = clean(input.text, LIMITS.text);
  if (!name) return { error: "Please tell us your name." };
  if (text.length < LIMITS.minText) return { error: `Please write at least ${LIMITS.minText} characters.` };
  if (!(input.consent === true || input.consent === "on" || input.consent === "true" || input.consent === "1")) return { error: "Please tick the box to allow us to publish this." };
  let rating = null;
  if (input.rating !== undefined && input.rating !== null && input.rating !== "") {
    rating = Number(input.rating);
    if (!Number.isInteger(rating) || rating < 1 || rating > 5) return { error: "Rating must be 1 to 5." };
  }
  const email = clean(input.email, 120).toLowerCase();
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return { error: "That email does not look right." };
  if (state.items.length >= LIMITS.maxItems) return { error: "This form is not accepting more right now." };
  const day = new Date(now).toISOString().slice(0, 10), rk = `${day}:${ipKey}`;
  for (const k of Object.keys(state.rate)) if (!k.startsWith(day)) delete state.rate[k];
  if ((state.rate[rk] || 0) >= LIMITS.perIpPerDay) return { error: "Too many submissions today. Please try again tomorrow." };
  if (state.items.some((i) => i.form === form.slug && i.text === text)) return { error: "ignored", silent: true }; // double-submit
  state.rate[rk] = (state.rate[rk] || 0) + 1;
  const item = { id, form: form.slug, name, role: clean(input.role, LIMITS.role), company: clean(input.company, LIMITS.company), text, rating, email, consent: true, status: "pending", at: now };
  state.items.push(item);
  return { item };
}

export function setStatus(state, id, status) {
  const it = state.items.find((i) => i.id === id);
  if (!it) return { error: "no such testimonial" };
  if (!["approved", "hidden", "pending"].includes(status)) return { error: "status must be approved, hidden or pending" };
  it.status = status;
  return { item: it };
}

export function remove(state, id) {
  const i = state.items.findIndex((x) => x.id === id);
  if (i < 0) return { error: "no such testimonial" };
  state.items.splice(i, 1);
  return { ok: true };
}

// Public view: approved only, never the email, newest first. Text is never edited by the host.
export function publicWall(state, formSlug, limit = 50) {
  return state.items.filter((i) => i.status === "approved" && (!formSlug || i.form === formSlug)).slice(-limit).reverse()
    .map(({ id, name, role, company, text, rating, at }) => ({ id, name, role, company, text, rating, at }));
}

export function stats(state) {
  const by = { pending: 0, approved: 0, hidden: 0 };
  let sum = 0, n = 0;
  for (const i of state.items) { by[i.status]++; if (i.status === "approved" && i.rating) { sum += i.rating; n++; } }
  return { forms: Object.keys(state.forms).length, total: state.items.length, ...by, averageRating: n ? Math.round((sum / n) * 100) / 100 : null, rated: n };
}

export function toCsv(items) {
  const cell = (v) => { let s = String(v ?? ""); if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
  return [["id", "form", "status", "name", "role", "company", "rating", "text", "email", "date"], ...items.map((i) => [i.id, i.form, i.status, i.name, i.role, i.company, i.rating ?? "", i.text, i.email, new Date(i.at).toISOString().slice(0, 10)])].map((r) => r.map(cell).join(",")).join("\n") + "\n";
}

